import{_ as o,c as e,b as n,o as r}from"./app-CoEY_fQ5.js";const i={};function a(l,t){return r(),e("div",null,t[0]||(t[0]=[n(`<p>In this section of the blog, you’ll find everything related to product configurations. Manage all your product settings seamlessly from this dedicated menu section</p><p>Here, you can provide an option to add/edit/delete the products to your sellers, you can enable the option to auto-approve your products, auto-enable the added products and much more.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2017/11/1-7.png" alt="product configuration Multivendor Marketplace for Shopify by Webkul"></p><p>Here are some new product configurations you might want to check out .</p><h3 id="add-video-to-product" tabindex="-1"><a class="header-anchor" href="#add-video-to-product"><span>Add Video to Product</span></a></h3><p>You can now add video while editing products. For this, you need to visit Multi-vendor admin panel&gt;&gt;Configuration&gt;&gt;Product Configuration and enable the tab are given below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_19_27-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_19_27"></p><p>Upload videos:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_36_31-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_36_31"></p><h3 id="add-product-origin-country-hsn-code-to-the-product-description" tabindex="-1"><a class="header-anchor" href="#add-product-origin-country-hsn-code-to-the-product-description"><span>Add Product Origin Country/HSN code to the Product Description</span></a></h3><p>The admin can allow sellers to add the country of their product origin to the description page. Visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Product Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1200x597.png" alt="image"></p><p>After enabling this, visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instruction for Marketplace</strong>:</p><p>Copy the following code into the product.liquid (or product-template, if exist) template inside form tag to display the &quot;Product Origin Country&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1-1200x597.png" alt="image-1"></p><p>So, when an admin and seller are adding/ editing any product then they have the option to choose the country of origin and fill the HSN code accordingly.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/country-1200x627.png" alt="country"></p><p>This is how it will look on the storefront:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-2.png" alt="image-2"></p><p><strong>Note</strong>: For existing products, you need to once save them to display this information on the frontend. Also, note that once the product is added, this can&#39;t be updated.</p><h3 id="allow-seller-to-add-cost-price" tabindex="-1"><a class="header-anchor" href="#allow-seller-to-add-cost-price"><span>ALLOW SELLER TO ADD COST PRICE</span></a></h3><p>Now, the admin can allow the seller to add the cost price which is the original product price.</p><p>The seller can enter the cost price while adding products from his respective seller panel.</p><p>The cost price will not be shown on the storefront and generally, it is used to calculate the profit margin.</p><p>Go to Admin panel &gt;&gt; Configurations &gt;&gt; product configuration &gt;&gt; Enable &quot; ALLOW SELLER TO ADD COST PRICE&quot; and click SAVE CHANGES button below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/cost-price-1200x627.png" alt="cost-price"></p><p>Now, when the seller will add products from his panel then he will have an option to add the cost price which should be less than the sales price.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/Add-Product-Seller-•-Multivendor-MarketPlace-1200x619.png" alt="Add-Product-Seller-•-Multivendor-MarketPlace"></p><h3 id="hide-product-tag-field" tabindex="-1"><a class="header-anchor" href="#hide-product-tag-field"><span>Hide Product Tag Field</span></a></h3><p>You can now hide the &quot;Product Tag&quot; field from the &quot;Add/Edit Product&quot; form.</p><p>For this, You need to visit the multi-vendor admin panel&gt;&gt;Configurations&gt;&gt;<strong>Product Configuration</strong>&gt;&gt;Enable the Tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Configuration-Admin-5-1200x597.png" alt="Configuration-Admin-5"></p><p>Once you enable this tab, you/sellers won&#39;t get the product tag field while adding a product.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Add-Product-Seller-•-Multivendor-MarketPlace-ssssssssssss-1200x597.png" alt="Add-Product-Seller-•-Multivendor-MarketPlace-ssssssssssss"></p><p>Note:- In case you add/edit products by CSV, make sure that the &quot;Restrict Product Tags&quot; is disable.</p><h3 id="product-form-help-text" tabindex="-1"><a class="header-anchor" href="#product-form-help-text"><span>Product Form Help Text</span></a></h3><h3 id="add-video-to-product-1" tabindex="-1"><a class="header-anchor" href="#add-video-to-product-1"><span>Add Video to Product</span></a></h3><p>You can now add video while editing products. For this, you need to visit Multi-vendor admin panel&gt;&gt;Configuration&gt;&gt;Product Configuration and enable the tab are given below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_19_27-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_19_27"></p><p>Upload videos:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_36_31-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_36_31"></p><h3 id="add-product-origin-country-hsn-code-to-the-product-description-1" tabindex="-1"><a class="header-anchor" href="#add-product-origin-country-hsn-code-to-the-product-description-1"><span>Add Product Origin Country/HSN code to the Product Description</span></a></h3><p>The admin can allow sellers to add the country of their product origin to the description page. Visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Product Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1200x597.png" alt="image"></p><p>After enabling this, visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instruction for Marketplace</strong>:</p><p>Copy the following code into the product.liquid (or product-template, if exist) template inside form tag to display the &quot;Product Origin Country&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1-1200x597.png" alt="image-1"></p><p>So, when an admin and seller are adding/ editing any product then they have the option to choose the country of origin and fill the HSN code accordingly.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/country-1200x627.png" alt="country"></p><p>This is how it will look on the storefront:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-2.png" alt="image-2"></p><p><strong>Note</strong>: For existing products, you need to once save them to display this information on the frontend. Also, note that once the product is added, this can&#39;t be updated.</p><h3 id="allow-seller-to-add-cost-price-1" tabindex="-1"><a class="header-anchor" href="#allow-seller-to-add-cost-price-1"><span>ALLOW SELLER TO ADD COST PRICE</span></a></h3><p>Now, the admin can allow the seller to add the cost price which is the original product price.</p><p>The seller can enter the cost price while adding products from his respective seller panel.</p><p>The cost price will not be shown on the storefront and generally, it is used to calculate the profit margin.</p><p>Go to Admin panel &gt;&gt; Configurations &gt;&gt; product configuration &gt;&gt; Enable &quot; ALLOW SELLER TO ADD COST PRICE&quot; and click SAVE CHANGES button below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/cost-price-1200x627.png" alt="cost-price"></p><p>Now, when the seller will add products from his panel then he will have an option to add the cost price which should be less than the sales price.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/Add-Product-Seller-•-Multivendor-MarketPlace-1200x619.png" alt="Add-Product-Seller-•-Multivendor-MarketPlace"></p><h3 id="hide-product-tag-field-1" tabindex="-1"><a class="header-anchor" href="#hide-product-tag-field-1"><span>Hide Product Tag Field</span></a></h3><p>You can now hide the &quot;Product Tag&quot; field from the &quot;Add/Edit Product&quot; form.</p><p>For this, You need to visit the multi-vendor admin panel&gt;&gt;Confi</p><h3 id="add-video-to-product-2" tabindex="-1"><a class="header-anchor" href="#add-video-to-product-2"><span>Add Video to Product</span></a></h3><p>You can now add video while editing products. For this, you need to visit Multi-vendor admin panel&gt;&gt;Configuration&gt;&gt;Product Configuration and enable the tab are given below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_19_27-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_19_27"></p><p>Upload videos:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/07/screenshot-sp-seller.webkul.com-2021.07.09-15_36_31-1200x549.png" alt="screenshot-sp-seller.webkul.com-2021.07.09-15_36_31"></p><h3 id="add-product-origin-country-hsn-code-to-the-product-description-2" tabindex="-1"><a class="header-anchor" href="#add-product-origin-country-hsn-code-to-the-product-description-2"><span>Add Product Origin Country/HSN code to the Product Description</span></a></h3><p>The admin can allow sellers to add the country of their product origin to the description page. Visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Product Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1200x597.png" alt="image"></p><p>After enabling this, visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instruction for Marketplace</strong>:</p><p>Copy the following code into the product.liquid (or product-template, if exist) template inside form tag to display the &quot;Product Origin Country&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-1-1200x597.png" alt="image-1"></p><p>So, when an admin and seller are adding/ editing any product then they have the option to choose the country of origin and fill the HSN code accordingly.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/country-1200x627.png" alt="country"></p><p>This is how it will look on the storefront:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/11/image-2.png" alt="image-2"></p><p><strong>Note</strong>: For existing products, you need to once save them to display this information on the frontend. Also, note that once the product is added, this can&#39;t be updated.</p><h3 id="allow-seller-to-add-cost-price-2" tabindex="-1"><a class="header-anchor" href="#allow-seller-to-add-cost-price-2"><span>ALLOW SELLER TO ADD COST PRICE</span></a></h3><p>Now, the admin can allow the seller to add the cost price which is the original product price.</p><p>The seller can enter the cost price while adding products from his respective seller panel.</p><p>The cost price will not be shown on the storefront and generally, it is used to calculate the profit margin.</p><p>Go to Admin panel &gt;&gt; Configurations &gt;&gt; product configuration &gt;&gt; Enable &quot; ALLOW SELLER TO ADD COST PRICE&quot; and click SAVE CHANGES button below.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/cost-price-1200x627.png" alt="cost-price"></p><p>Now, when the seller will add products from his panel then he will have an option to add the cost price which should be less than the sales price.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/07/Add-Product-Seller-•-Multivendor-MarketPlace-1200x619.png" alt="Add-Product-Seller-•-Multivendor-MarketPlace"></p><h3 id="hide-product-tag-field-2" tabindex="-1"><a class="header-anchor" href="#hide-product-tag-field-2"><span>Hide Product Tag Field</span></a></h3><p>You can now hide the &quot;Product Tag&quot; field from the &quot;Add/Edit Product&quot; form.</p><p>For this, You need to visit the multi-vendor admin panel&gt;&gt;Confi</p><p>Add help text to product form labels for both admin &amp; seller end.</p><p>Visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Product Configuration</strong>. Enable this tab:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/08/image-1200x597.png" alt="image"></p><p>Now, to add the help text, visit Multivendor Admin Panel &gt; Products &gt; Product Form Customization. Add the help text and save:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/08/image-1-1200x597.png" alt="image-1"></p><p><strong>Note these points:</strong></p><ul><li>Product form customization is valid only for normal and digital product and it does not include Global Products.</li><li>It will not affect product CSV format.</li></ul><p>This is how they will look on the add product page (both admin &amp; seller end):</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/08/image-2-1200x584.png" alt="image-2"></p><h3 id="product-re-approve-feature" tabindex="-1"><a class="header-anchor" href="#product-re-approve-feature"><span>Product Re-Approve feature</span></a></h3><p>Now, once a seller edits a product, the admin can approve/disapprove the updates before they become live on the storefront.</p><p>Configure this by visiting <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Product Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-169-1200x597.png" alt="image-169"></p><p>Now, whenever a seller updates a product, the admin will receive an email to approve it. If the admin disapproves, he need to mention the reason for disapproval.</p><p>Note that on disapproving, only the product updates will disapprove and not the whole product. Also, the admin needs to manually check what all updates the seller has done.</p><p>This will be the status of the product on both admin and seller end:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-170-1200x597.png" alt="image-170"></p><p>If the admin disapproves, he need to mention a reason for the same:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-171-1200x597.png" alt="image-171"></p><p>Once approved, the product updates will become live on the storefront.</p><p><strong>NOTE</strong>: In case the admin saves the product after going on the edit product page, the product will get approved.</p><h3 id="product-update-by-csv" tabindex="-1"><a class="header-anchor" href="#product-update-by-csv"><span>Product Update by CSV</span></a></h3><p>Now, the admin/sellers can edit products in bulk. All you have to do is visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Products</strong> &gt; <strong>Product Listing</strong> &gt; <strong>More Actions</strong> &gt; <strong>Add product via CSV</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-167-1200x597.png" alt="image-167"></p><p>In <strong>method 1</strong>, you just need to upload the updated/edited CSV file.</p><p>Make sure in the CSV file that you are uploading, the <strong>Product IDs</strong> are the same as that of the <strong>existing products</strong> you are trying to update.</p><p>If the product IDs don&#39;t match, the existing products will not be updated and new products will be created.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-168-1200x597.png" alt="image-168"></p><h3 id="allow-sellers-to-set-the-product-price-to-zero" tabindex="-1"><a class="header-anchor" href="#allow-sellers-to-set-the-product-price-to-zero"><span>ALLOW SELLERS TO SET THE PRODUCT PRICE TO ZERO</span></a></h3><p>The admin can allow his/her sellers to create products with product price being zero.</p><p>In that case, the product will become a free product. You can configure it by visiting: <strong>Multivendor admin panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Products Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/download.png" alt="download"></p><p><strong>Note</strong>: No commission will be calculated on free product and if you have set fixed commission, this feature won&#39;t work with Display Sales Price.</p><p>Also, this feature will only work if you have set fixed commission and not % or anything else.</p><h3 id="allow-seller-to-set-minimum-purchase-quantity-per-product" tabindex="-1"><a class="header-anchor" href="#allow-seller-to-set-minimum-purchase-quantity-per-product"><span>ALLOW SELLER TO SET MINIMUM PURCHASE QUANTITY PER PRODUCT</span></a></h3><p>From this option, you can allow the seller to set a minimum purchase quantity for products.</p><p>This way, the customers will get restricted to buy the set number of quantity for the respective products.</p><p>To configure this, visit:</p><p><strong>Multivendor admin panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Products Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/12/Configuration-Admin-4-1200x627.png" alt="Configuration-Admin-4"></p><p>Now, while adding products to the marketplace (admin panel or seller panel), you&#39;ll get the option to set quantity. Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/12/Add-Product-Admin-1-1200x627.png" alt="Add-Product-Admin-1"></p><p>Know in-depth: <a href="https://webkul.com/blog/minimum-purchase-quantity-multi-vendor-marketplace-for-shopify/" target="_blank" rel="noopener noreferrer">https://webkul.com/blog/minimum-purchase-quantity-multi-vendor-marketplace-for-shopify/</a></p><h3 id="shopify-multivendor-product-sync" tabindex="-1"><a class="header-anchor" href="#shopify-multivendor-product-sync"><span>SHOPIFY-MULTIVENDOR PRODUCT SYNC</span></a></h3><p>If you make any changes to your products from Shopify end, you need to sync the products each time with the app to reflect the updates made at the multivendor end too.</p><p><em><strong>It is advisable to make any changes in the products at the multivendor end because this way the products get auto-updated at Shopify too. But not vice-versa.</strong></em></p><p>Let&#39;s see the syncing process.</p><p>To sync a single product, go to <strong>multivendor admin panel</strong> &gt; <strong>products</strong> &gt; <strong>product listing</strong> &gt; <strong>edit</strong> the product like so:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Product-Admin-1-1-1200x597.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Now, on the redirected page, click on <strong>more actions</strong> &gt; <strong>sync product</strong>. Refer:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Edit-Product-Admin-1-1200x597.png" alt="MULTIVENDOR MARKETPLACE"></p><p><strong>Bulk Sync Process:</strong></p><p>Go to <strong>multivendor admin panel</strong> &gt; <strong>products</strong> &gt; <strong>product listing</strong> &gt; select the products you want to sync &gt; from <strong>bulk action</strong>, click on <strong>sync selected</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Product-Admin-2-1-1200x597.png" alt="MULTIVENDOR MARKETPLACE"></p><h3 id="sync-orders-updates" tabindex="-1"><a class="header-anchor" href="#sync-orders-updates"><span>Sync Orders Updates</span></a></h3><p>When an item is purchased from your Shopify store, the inventory will only be synced with the app if the item is assigned to any seller registered on your marketplace.</p><p>Now, to fetch orders into the app, you need to click the Sync Orders button and sync your Shopify orders with the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Orders-Admin-1200x619.png" alt="Orders-Admin"></p><h3 id="product-type-product-tag-collection-at-seller-panel" tabindex="-1"><a class="header-anchor" href="#product-type-product-tag-collection-at-seller-panel"><span>PRODUCT TYPE, PRODUCT TAG &amp; COLLECTION AT SELLER PANEL</span></a></h3><p>Now, the sellers have the following menus in their multivendor seller panel: Product Type, Product Tag &amp; Collections.</p><p>Multivendor Seller Panel &gt; Products:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Dashboard-Seller-•-Multivendor-MarketPlace-1.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Moreover, sellers will also have an option to <strong>export</strong> product tags, types &amp; collections.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/Collections-Seller-•-Multivendor-MarketPlace.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Example: Multivendor Seller Panel &gt; Products &gt; Collections</p><h3 id="edit-image-alt-text" tabindex="-1"><a class="header-anchor" href="#edit-image-alt-text"><span>EDIT IMAGE ALT TEXT</span></a></h3><p>In our new updates, while editing products on Multi-Vendor Marketplace, the admin/seller will get an option to add <strong>alt text</strong> to the product images.</p><p>ALT text is basically your image description. Google bots examine these descriptions and rank them accordingly. Thus, they help a lot with SEO.</p><p>For this, visit <strong>Multi-Vendor Marketplace Admin/Seller Panel</strong> &gt; <strong>Products</strong> &gt; <strong>Product Listing</strong> &gt; <strong>Edit Product</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/08/01071527/AwesomeScreenshot-shopify-trunk-webkul-shopify-mp-admin-index.php-2019-08-01_12_45-1200x597.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Click on <strong>Edit Image</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/01071652/AwesomeScreenshot-shopify-trunk-webkul-shopify-mp-admin-index.php-2019-08-01_12_46.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Hover over the image and then click on <strong>ALT</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/08/01071902/AwesomeScreenshot-shopify-trunk-webkul-shopify-mp-admin-index.php-2019-08-01_12_48.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Now enter the ALT text and save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/08/01072010/AwesomeScreenshot-shopify-trunk-webkul-shopify-mp-admin-index.php-2019-08-01_12_49.png" alt="MULTIVENDOR MARKETPLACE"></p><p>Similarly, you add alt text to multiple images of a product.</p><h3 id="import-products-from-shopify" tabindex="-1"><a class="header-anchor" href="#import-products-from-shopify"><span>IMPORT PRODUCTS FROM SHOPIFY</span></a></h3><p>By enabling the import product button from the product section of the configuration,</p><p>And then visiting the imported product from Shopify from the main menu will enable the user to import the product either by selecting the period</p><p>And entering to and from the date or it can be imported by uploading a CSV.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/Import-Product-From-Shopify-_-Admin.jpg" alt="MULTIVENDOR MARKETPLACE"></p><p><em>Important Note: All of these imported products will be visible on the product section only after the products are assigned by admin to any seller.</em></p><h3 id="product-form-customization" tabindex="-1"><a class="header-anchor" href="#product-form-customization"><span>PRODUCT FORM CUSTOMIZATION</span></a></h3><p>With this section, you can hide/unhide the components of product form.</p><p>Click on Product Form Customization from the main menu of the app and select the products you want to remove from the add product page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2016/02/24.png" alt="MULTIVENDOR MARKETPLACE"></p><h3 id="hide-show-product-images-in-product-listing" tabindex="-1"><a class="header-anchor" href="#hide-show-product-images-in-product-listing"><span>HIDE/SHOW PRODUCT IMAGES IN PRODUCT LISTING</span></a></h3><p>You can now hide/show the product images in the product listing section by enabling/disabling the below configuration from the product configuration section.</p><p>Multivendor Marketplace App Admin panel&gt;&gt;Configuration&gt;&gt;Product Configuration&gt;&gt; Enable/disable <strong>SHOW PRODUCT IMAGE FIELD UNDER &quot;PRODUCT LISTING&quot;</strong> SECTION&gt;&gt;Save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Configuration-_-Admin-1200x439.png" alt="Configuration-_-Admin"></p><p>Once you enable this tab, Product Images will be visible in the product listing section on both the admin and seller panels.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Product-_-Admin-3-1200x475.png" alt="Product-_-Admin-3"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Product-_-Seller-•-Multivendor-MarketPlace-2-1200x443.png" alt="Product-_-Seller-•-Multivendor-MarketPlace-2"></p><p>If you disable the <strong>SHOW PRODUCT IMAGE FIELD UNDER &quot;PRODUCT LISTING&quot;</strong> SECTION configuration, the product images will not be visible in the product listing section on both the admin and seller panels.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Configuration-_-Admin-1-1-1200x457.png" alt="Configuration-_-Admin-1-1"></p><p>This is how the Admin and Seller Panel will look after the configuration is disable.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Product-_-Admin-2-1200x492.png" alt="Product-_-Admin-2"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Product-_-Seller-•-Multivendor-MarketPlace-1-1200x443.png" alt="Product-_-Seller-•-Multivendor-MarketPlace-1"></p><h3 id="export-product-details-at-seller-panel" tabindex="-1"><a class="header-anchor" href="#export-product-details-at-seller-panel"><span>EXPORT PRODUCT DETAILS AT SELLER PANEL</span></a></h3><p>Now, the sellers have the <strong>Export Details</strong> option in the product listing section in their multivendor seller panel.</p><p>Multivendor Marketplace App Seller Panel&gt;&gt;Products&gt;&gt;Product listing:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/12/Product-_-Seller-•-Multivendor-MarketPlace-5-1200x472.png" alt="Product-_-Seller-•-Multivendor-MarketPlace-5"></p><h3 id="product-price-round-off" tabindex="-1"><a class="header-anchor" href="#product-price-round-off"><span>PRODUCT PRICE ROUND OFF</span></a></h3><p>Product price round-off will help the admin to replace a product price number with an approximate value that has decimal value representation. For example, replacing $23.883 with $23.88.</p><p>By enabling the product price round-off, a dropdown will appear to select the decimal for the product price round off and select the &quot;decimal number to be round off&quot; from the dropdown.</p><p>Click the SAVE button.</p><p>For example, if you have selected &quot;2&quot; from the decimal dropdown then decimal numbers like 22.773 round off to 22.77, 23.889 round off to 23.89, and if you have selected &quot;1&quot; from the decimal dropdown</p><p>then decimal numbers like 22.673 round off to 22.7, 23.889 round off to 23.9</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/04/round-off-.png" alt="round-off-"></p><p>NOTE:<br> Product price round-off will be applied on product price, its compare at price, variant price, and its compare at price.</p><h3 id="product-variant-inventory-listings" tabindex="-1"><a class="header-anchor" href="#product-variant-inventory-listings"><span>Product Variant Inventory Listings</span></a></h3><p>When a customer purchases a product variant, the sold variant is listed in the Variant Inventory section of both the Admin and Seller panels.</p><p>They can view all variant orders by navigating to <strong>Products &gt; Variant Inventory</strong> in their panel. Additionally, they can check the remaining variant inventory by location.</p><p>Admin Panel:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/12/variad-1200x494.webp" alt="Variant Admin"></p><p>Admins can easily manage inventory by filtering the product variant inventory list using <strong>&quot;Out of Stock&quot;,</strong> <strong>&quot;Inventory Tracked&quot;</strong> and <strong>&quot;Inventory Not Tracked&quot;</strong> options.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/inventory-1200x559.webp" alt="Filter"></p><p>Seller Panel:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/12/varisel-1200x532.webp" alt="Variant Seller"></p><h3 id="manage-products-as-draft-product" tabindex="-1"><a class="header-anchor" href="#manage-products-as-draft-product"><span>Manage products as Draft Product</span></a></h3><p><strong>Introducing the Draft Feature for Sellers!</strong></p><p>Sellers now have the flexibility to save their products as drafts before making them live.</p><p>To enable this feature, the Admin needs to activate the <strong>&quot; Save Product as a Draft&quot;</strong> option.</p><p>This setting can be easily configured in the <strong>Product Configuration</strong> section, giving sellers better control over their product listings.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/testt.webp" alt="Product configuration"></p><p>Once the Admin enables this option, sellers will see the <strong>&quot;Save as Draft&quot;</strong> feature while adding products. This allows them to save incomplete listings and publish them later when ready.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft3-1200x858.webp" alt="save draft"></p><p>When you click on <strong>Edit Product</strong>, you can view the current status of the product. Sellers can then update the status from <strong>&quot;Draft&quot;</strong> to <strong>&quot;Ready for Approval&quot;</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft5-1200x858.webp" alt="status"></p><p>Once updated, the <strong>&quot;Approval Pending&quot;</strong> status will be visible in the <strong>Product Details</strong> section.</p><p>We’ve made the workflow even smoother! If the <strong>&quot;Auto Approve Product&quot;</strong> setting is enabled by the Admin,</p><p>sellers can now <strong>directly approve their own draft products</strong> without waiting for manual approval.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft-product-1200x943.webp" alt="draft-product"></p><h3 id="mvm-admin-seller-draft-product-reflected-in-shopify-s-draft-product-list" tabindex="-1"><a class="header-anchor" href="#mvm-admin-seller-draft-product-reflected-in-shopify-s-draft-product-list"><span>MVM Admin &amp; Seller Draft product Reflected in Shopify&#39;s draft product List</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft1-1-1200x943.webp" alt="draft1"></p><p>On admin panel -&gt;Configuration-&gt; Product Configuration then turn on &#39;<strong>CREATE PRODUCT AS DRAFT ON SHOPIFY</strong>&#39; configuration.</p><p>By allowing this configuration, When a product is created as a draft by the admin or seller in MVM, it will automatically appear in your Shopify product list for further editing or publishing.</p><h3 id="product-preview-button-for-draft-items-admin-seller" tabindex="-1"><a class="header-anchor" href="#product-preview-button-for-draft-items-admin-seller"><span>Product Preview button for Draft Items (Admin &amp; Seller)</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft2-1-1200x943.webp" alt="draft2
"></p><p>Both MVM admin and seller panels now include a <strong>Preview</strong> <strong>button</strong> for draft products, enabling users to see the product detail page layout prior to making it live on thier Stores.</p><p><strong>Draft Status for CSV-Added Products</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/draft3-1-1200x859.webp" alt="draft3"></p><p>Now, Products uploaded via CSV by both sellers and admins have option to select product status either as <strong>Draft</strong> status or Active Status.</p><p><strong>Shopify Taxonomy category added to the product form</strong></p><p>We&#39;ve added a new option to the Product form: Shopify Taxonomy Category, making product categorization easier and more accurate.</p><p>To display this field in the product form, the Admin can enable the Product taxonomy category config.</p><p>To enable, go to Multivendor Admin Panel &gt; Configuration &gt; Product Configuration, and enable the <strong>Product Taxonomy Category</strong> config.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/taxo.webp" alt="Product configuration"></p><p>Then, go to the <strong>Product Form Customization</strong> section and make sure the <strong>Product Taxonomy Category</strong> field is marked as visible.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/productfor.webp" alt="Product form Customisation"></p><p>Once these steps are completed, the field will appear in the product form.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/blog2-1200x572.webp" alt="Product category"></p><p>Additionally, this option has been added to <strong>Dual Sync</strong>.</p><p>If the admin wants to sync product categories from <strong>Shopify to Multivendor</strong>, they can go to the <strong>Dual Sync</strong> section and select <strong>Product Taxonomy Category</strong> for syncing.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dualsync.webp" alt="Dual sync"></p><p><strong>Separate filters &quot;Filter By&quot; &amp; &quot;Search By&quot; at Product Listing</strong></p><p>We’ve enhanced the product listing page by adding more specific filter options for admins and sellers. These new filters make it easier to manage and organize products efficiently.</p><p>Admins and sellers can now filter products by status, such as Global Product, Approved, Approval Pending, and more, using the available filters.</p><p>Additionally, they can perform a specific search using the &#39;Search by&#39; option simultaneously.</p><p>Both the filter and search functionalities also work independently.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/filter-1200x535.webp" alt="filter by"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/filter2-1200x531.webp" alt="search by"></p><p>However, admins and sellers can conveniently search using the “Search by” option.</p>`,254)]))}const d=o(i,[["render",a]]),s=JSON.parse(`{"path":"/zenith/configuration/product-configration.html","title":"Multivendor Marketplace:Product configuration","lang":"en-US","frontmatter":{"title":"Multivendor Marketplace:Product configuration","description":"Learn about product configuration.","date":"2025-06-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Add Video to Product","slug":"add-video-to-product","link":"#add-video-to-product","children":[]},{"level":3,"title":"Add Product Origin Country/HSN code to the Product Description","slug":"add-product-origin-country-hsn-code-to-the-product-description","link":"#add-product-origin-country-hsn-code-to-the-product-description","children":[]},{"level":3,"title":"ALLOW SELLER TO ADD COST PRICE","slug":"allow-seller-to-add-cost-price","link":"#allow-seller-to-add-cost-price","children":[]},{"level":3,"title":"Hide Product Tag Field","slug":"hide-product-tag-field","link":"#hide-product-tag-field","children":[]},{"level":3,"title":"Product Form Help Text","slug":"product-form-help-text","link":"#product-form-help-text","children":[]},{"level":3,"title":"Add Video to Product","slug":"add-video-to-product-1","link":"#add-video-to-product-1","children":[]},{"level":3,"title":"Add Product Origin Country/HSN code to the Product Description","slug":"add-product-origin-country-hsn-code-to-the-product-description-1","link":"#add-product-origin-country-hsn-code-to-the-product-description-1","children":[]},{"level":3,"title":"ALLOW SELLER TO ADD COST PRICE","slug":"allow-seller-to-add-cost-price-1","link":"#allow-seller-to-add-cost-price-1","children":[]},{"level":3,"title":"Hide Product Tag Field","slug":"hide-product-tag-field-1","link":"#hide-product-tag-field-1","children":[]},{"level":3,"title":"Add Video to Product","slug":"add-video-to-product-2","link":"#add-video-to-product-2","children":[]},{"level":3,"title":"Add Product Origin Country/HSN code to the Product Description","slug":"add-product-origin-country-hsn-code-to-the-product-description-2","link":"#add-product-origin-country-hsn-code-to-the-product-description-2","children":[]},{"level":3,"title":"ALLOW SELLER TO ADD COST PRICE","slug":"allow-seller-to-add-cost-price-2","link":"#allow-seller-to-add-cost-price-2","children":[]},{"level":3,"title":"Hide Product Tag Field","slug":"hide-product-tag-field-2","link":"#hide-product-tag-field-2","children":[]},{"level":3,"title":"Product Re-Approve feature","slug":"product-re-approve-feature","link":"#product-re-approve-feature","children":[]},{"level":3,"title":"Product Update by CSV","slug":"product-update-by-csv","link":"#product-update-by-csv","children":[]},{"level":3,"title":"ALLOW SELLERS TO SET THE PRODUCT PRICE TO ZERO","slug":"allow-sellers-to-set-the-product-price-to-zero","link":"#allow-sellers-to-set-the-product-price-to-zero","children":[]},{"level":3,"title":"ALLOW SELLER TO SET MINIMUM PURCHASE QUANTITY PER PRODUCT","slug":"allow-seller-to-set-minimum-purchase-quantity-per-product","link":"#allow-seller-to-set-minimum-purchase-quantity-per-product","children":[]},{"level":3,"title":"SHOPIFY-MULTIVENDOR PRODUCT SYNC","slug":"shopify-multivendor-product-sync","link":"#shopify-multivendor-product-sync","children":[]},{"level":3,"title":"Sync Orders Updates","slug":"sync-orders-updates","link":"#sync-orders-updates","children":[]},{"level":3,"title":"PRODUCT TYPE, PRODUCT TAG & COLLECTION AT SELLER PANEL","slug":"product-type-product-tag-collection-at-seller-panel","link":"#product-type-product-tag-collection-at-seller-panel","children":[]},{"level":3,"title":"EDIT IMAGE ALT TEXT","slug":"edit-image-alt-text","link":"#edit-image-alt-text","children":[]},{"level":3,"title":"IMPORT PRODUCTS FROM SHOPIFY","slug":"import-products-from-shopify","link":"#import-products-from-shopify","children":[]},{"level":3,"title":"PRODUCT FORM CUSTOMIZATION","slug":"product-form-customization","link":"#product-form-customization","children":[]},{"level":3,"title":"HIDE/SHOW PRODUCT IMAGES IN PRODUCT LISTING","slug":"hide-show-product-images-in-product-listing","link":"#hide-show-product-images-in-product-listing","children":[]},{"level":3,"title":"EXPORT PRODUCT DETAILS AT SELLER PANEL","slug":"export-product-details-at-seller-panel","link":"#export-product-details-at-seller-panel","children":[]},{"level":3,"title":"PRODUCT PRICE ROUND OFF","slug":"product-price-round-off","link":"#product-price-round-off","children":[]},{"level":3,"title":"Product Variant Inventory Listings","slug":"product-variant-inventory-listings","link":"#product-variant-inventory-listings","children":[]},{"level":3,"title":"Manage products as Draft Product","slug":"manage-products-as-draft-product","link":"#manage-products-as-draft-product","children":[]},{"level":3,"title":"MVM Admin & Seller Draft product Reflected in Shopify's draft product List","slug":"mvm-admin-seller-draft-product-reflected-in-shopify-s-draft-product-list","link":"#mvm-admin-seller-draft-product-reflected-in-shopify-s-draft-product-list","children":[]},{"level":3,"title":"Product Preview button for Draft Items (Admin & Seller)","slug":"product-preview-button-for-draft-items-admin-seller","link":"#product-preview-button-for-draft-items-admin-seller","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":2,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"769a52a9d6ea585a51f97bd9091014ed466fba2c","time":1751543091000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"zenith/configuration/product-configration.md"}`);export{d as comp,s as data};
